import _codecs
source = b'\xff'
for replacement in [b'', b'A', b'AB', b'ABC', b'\xff', b'\xed\xa0\x80', b'\x00\xdcA', br'\u1234', b'+A']:
    for resume in [0, -1, -2, 1]:
        for final in [False, True]:
            events = []
            faults = []
            def handler(error):
                faults.append(error)
                events.append((error.object, error.start, error.end, error.reason, error.args))
                if len(events) == 1:
                    error.object = replacement
                    return ('?', resume)
                return ('!', len(error.object))
            _codecs.register_error('replacement_matrix', handler)
            try:
                result = _codecs.utf_8_decode(source, 'replacement_matrix', final)
            except Exception as error:
                result = (type(error).__name__, error.args)
            print(replacement, resume, final, result, events)
            if faults:
                assert faults[0].object is replacement
                for fault in faults:
                    assert fault is faults[0]
                    assert fault.args is events[0][4]

